import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { prepareReview } from '../input/scripts/directions/review.mjs'
import { resolveRole, createRoleAuthority } from '../input/scripts/directions/roles.mjs'
import { createArtifactReader } from '../input/scripts/directions/evidence.mjs'
import { projectStatus } from '../input/scripts/directions/status.mjs'
const m = JSON.parse(readFileSync('../input/docs/engineering/directions/frade-standard-workflow/direction.json'))
const prefix = 'openspec/changes/frade-standard-workflow/'
const request = {
  stage: 'W01', change: m.id, phase: 'POST', role: 'independent-POST', taskType: 'independent-POST',
  task: '4.2', scope: 'cumulative W01', prompt: 'Review the complete approved candidate.',
  paths: ['AGENTS.md', ...['proposal.md','design.md','tasks.md','specs/engineering-direction-lifecycle/spec.md','specs/engineering-role-dispatch/spec.md','specs/engineering-progress-publication/spec.md','evidence/user-decisions.json','evidence/policy-acceptance.json'].map(p=>prefix+p),m.policy.artifact,m.statusPath]
}
// Rejects at pure request validation, before any Git or original-owner access.
const review = await prepareReview({manifest:m,request,root:resolve('../input')})
let approvalCalls=0
const authority=createRoleAuthority({bindings:[{path:prefix+'design.md',sha256:m.stages[0].roleAuthority.hash,revision:'D03'},{path:prefix+'evidence/policy-acceptance.json',sha256:m.policyAcceptance.sha256,revision:'D03'}],verifyApproval:async()=>{approvalCalls++;return false}})
const roles=[]
for(const row of m.stages[0].roleAssignments){
 const r=await resolveRole({manifest:m,stageId:'W01',taskId:'4.1',taskType:row.role,role:row.role,reader:createArtifactReader(resolve('../input')),authority})
 roles.push({role:row.role,status:r.status,issue:r.issues[0]})
}
const source=readFileSync('../input/scripts/directions/bootstrap.mjs','utf8')
const tasks=[...source.matchAll(/'(- \[ \] S01\.\d[^']+)'/g)].map(x=>x[1]).join('\n')
const status=await projectStatus({manifest:m,tasksText:tasks,snapshot:{sourceSha256:'a'.repeat(64),configSha256:'b'.repeat(64)}})
console.log(JSON.stringify({runtime:process.version,review,roles,approvalCalls,bootstrapTasks:tasks,projection:{issues:status.issues,tasks:status.metrics.tasks}},null,2))
